{
  "name": "Hamilton倾斜模块",
  "name_en": "Hamilton Tilt Module",
  "manufacturer": "Hamilton",
  "description": "这是一种用于实验室自动化平台的机械倾斜模块，可按设定角度或位置倾斜样品载具，以辅助液体排空、沉降、分离或处理过程中的姿态控制。根据配置不同，模块还可带有加热、编码器、传感器输入、开集电极输出以及废液泵等功能。",
  "description_en": "A mechanical tilting module for laboratory automation platforms that tilts sample carriers to defined angles or positions to support liquid draining, settling, separation, or controlled sample handling. Depending on configuration, the module may also include heating, an encoder, sensor inputs, open-collector outputs, and a waste pump.",
  "tag_hints": [
    "plate tilting",
    "lab automation",
    "liquid draining",
    "sample positioning",
    "optional heating",
    "waste pump",
    "sensor I/O"
  ],
  "actions": [
    {
      "action_name": "auto-send_command",
      "description": "向倾斜模块发送底层命令。",
      "description_en": "Send a low-level command to the tilt module."
    },
    {
      "action_name": "auto-set_angle",
      "description": "设置倾斜模块的旋转角度。",
      "description_en": "Set the rotation angle of the tilt module."
    },
    {
      "action_name": "auto-setup",
      "description": "初始化倾斜模块，并设置初始偏移。",
      "description_en": "Initialize the tilt module and set the initial offset."
    },
    {
      "action_name": "auto-stop",
      "description": "停止倾斜模块运行。",
      "description_en": "Stop the tilt module."
    },
    {
      "action_name": "auto-tilt_go_to_position",
      "description": "将倾斜模块移动到预定义倾斜位置。",
      "description_en": "Move the tilt module to a predefined tilt position."
    },
    {
      "action_name": "auto-tilt_initial_offset",
      "description": "设置倾斜模块的初始偏移量。",
      "description_en": "Set the initial offset of the tilt module."
    },
    {
      "action_name": "auto-tilt_initialize",
      "description": "初始化菊链连接的倾斜模块。",
      "description_en": "Initialize a daisy-chained tilt module."
    },
    {
      "action_name": "auto-tilt_move_to_absolute_step_position",
      "description": "将倾斜模块移动到绝对步进位置。",
      "description_en": "Move the tilt module to an absolute step position."
    },
    {
      "action_name": "auto-tilt_move_to_relative_step_position",
      "description": "使倾斜模块按相对步数移动。",
      "description_en": "Move the tilt module by a relative number of steps."
    },
    {
      "action_name": "auto-tilt_port_clear_open_collector",
      "description": "关闭指定开集电极输出。",
      "description_en": "Clear the specified open-collector output."
    },
    {
      "action_name": "auto-tilt_port_set_open_collector",
      "description": "打开指定开集电极输出。",
      "description_en": "Set the specified open-collector output."
    },
    {
      "action_name": "auto-tilt_power_off",
      "description": "关闭倾斜模块电源。",
      "description_en": "Power off the tilt module."
    },
    {
      "action_name": "auto-tilt_request_error",
      "description": "获取倾斜模块当前错误状态。",
      "description_en": "Get the current error status of the tilt module."
    },
    {
      "action_name": "auto-tilt_request_offset_between_light_barrier_and_init_position",
      "description": "获取光障与初始位置之间的偏移量。",
      "description_en": "Get the offset between the light barrier and the initialization position."
    },
    {
      "action_name": "auto-tilt_request_sensor",
      "description": "获取倾斜模块传感器输入状态。",
      "description_en": "Get the sensor input status of the tilt module."
    },
    {
      "action_name": "auto-tilt_set_drain_time",
      "description": "设置废液排放时间。",
      "description_en": "Set the waste drain time."
    },
    {
      "action_name": "auto-tilt_set_name",
      "description": "设置倾斜模块名称。",
      "description_en": "Set the tilt module name."
    },
    {
      "action_name": "auto-tilt_set_speed",
      "description": "设置倾斜模块移动速度。",
      "description_en": "Set the movement speed of the tilt module."
    },
    {
      "action_name": "auto-tilt_set_temperature",
      "description": "设置倾斜模块加热温度。",
      "description_en": "Set the heating temperature of the tilt module."
    },
    {
      "action_name": "auto-tilt_set_waste_pump_off",
      "description": "关闭废液泵。",
      "description_en": "Turn the waste pump off."
    },
    {
      "action_name": "auto-tilt_set_waste_pump_on",
      "description": "开启废液泵。",
      "description_en": "Turn the waste pump on."
    },
    {
      "action_name": "auto-tilt_switch_encoder",
      "description": "打开或关闭编码器。",
      "description_en": "Turn the encoder on or off."
    },
    {
      "action_name": "auto-tilt_switch_off_temperature_controller",
      "description": "关闭温度控制器。",
      "description_en": "Switch off the temperature controller."
    }
  ]
}

